insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_51_v1'
from (values
('127.294.d.1.A',3,'A practicum student must give a supervisor an update on a task. Which approach is clearest?','["Give a short spoken summary and follow up with a written note", "Wait until the supervisor asks", "Send only an emoji", "Mumble and hope the supervisor understands"]'::jsonb,0,'Combining clear speaking with a written record communicates effectively.','original'),
('127.294.d.1.A',4,'Which written message to a work-site mentor is most professional?','["A text of all capital letters", "A brief email with a greeting, the request, and a thank-you", "A message with slang and no greeting", "A long message with no clear request"]'::jsonb,1,'Professional writing is clear, polite, and purposeful.','original'),
('127.294.d.2.A',3,'Why should a practicum student review the course requirements before the work experience begins?','["To avoid doing any assigned tasks", "To pick a different course", "To connect on-the-job tasks to what the course expects them to learn", "To skip the evaluation"]'::jsonb,2,'Knowing the requirements guides what to practice and document.','original'),
('127.294.d.2.A',4,'A student notices a work-site task is unrelated to the course goals. The best next step is to:','["Do only the unrelated task", "Quit the placement", "Quietly ignore the course goals", "Ask the teacher and supervisor how to align the tasks with the course"]'::jsonb,3,'Alignment keeps the experience useful for the course.','original'),
('127.294.d.2.B',3,'Mastering a hands-on skill to an industry standard means performing it:','["Accurately and safely the way professionals in the field do", "Only once", "Differently each time", "Quickly but carelessly"]'::jsonb,0,'Industry standards define accuracy, safety, and quality.','original'),
('127.294.d.2.B',4,'Which habit best builds mastery of a technical skill during a practicum?','["Practicing only when convenient", "Repeated supervised practice with feedback", "Watching without trying", "Skipping directions"]'::jsonb,1,'Practice plus feedback builds mastery.','original'),
('127.294.d.2.C',3,'An industry-recognized credential shows that a student has:','["Joined a club", "Paid a parking fee", "Met a standard set by the industry for a skill", "Finished a school dance"]'::jsonb,2,'Credentials document verified skills.','original'),
('127.294.d.2.C',4,'A student earning a certification while in a practicum should keep:','["Only a nickname", "Nothing, since employers ignore it", "Only a guess of the date", "Records of tests passed and hours worked"]'::jsonb,3,'Documentation proves progress toward the credential.','original'),
('127.295.d.1.A',3,'Which step best helps a student assess their own marketability to employers?','["List skills, training, and experience and compare them to job postings", "Guess based on mood", "Copy a friend''s list", "Wait for an offer before reviewing"]'::jsonb,0,'Comparing strengths to job needs shows marketability.','original'),
('127.295.d.1.A',4,'A student finds that postings often ask for a certification the student lacks. The most useful response is to:','["Stop job searching", "Plan how to earn that certification", "Lie on the application", "Ignore the postings"]'::jsonb,1,'Closing a skill gap raises marketability.','original'),
('127.295.d.1.C',3,'Which outfit and attitude best fit a job interview for an office position?','["Wrinkled shirt and a bored look", "Beachwear and loud talk", "Clean, neat business attire and a positive attitude", "Costume clothes"]'::jsonb,2,'Professional dress and attitude create a good first impression.','original'),
('127.295.d.1.C',4,'During an interview, which behavior best shows professionalism?','["Interrupting the interviewer", "Checking a phone during questions", "Arriving late with an excuse", "A firm handshake, eye contact, and a prompt arrival"]'::jsonb,3,'These behaviors show respect and reliability.','original'),
('127.295.d.1.D',3,'At a mock interview, you are asked to describe a strength. Your best answer includes:','["A specific strength with a short example", "Only the word ''nothing''", "A joke instead of an answer", "A complaint about a past boss"]'::jsonb,0,'Specific examples make answers credible.','original'),
('127.295.d.1.D',4,'After being asked a question you did not expect, an interviewee should:','["Freeze and say nothing", "Pause, think, and give an honest, organized answer", "Make up facts", "Change the subject"]'::jsonb,1,'Composed, honest answers show good interview technique.','original'),
('127.295.d.1.F',3,'Which skill most helps an employee advance to a higher position?','["Avoiding new tasks", "Waiting to be told everything", "Taking initiative and continuing to learn", "Skipping training"]'::jsonb,2,'Initiative and learning support promotion.','original'),
('127.295.d.1.F',4,'An employee wants a promotion in a year. The best plan is to:','["Hope someone notices", "Complain about the manager", "Do the minimum", "Set goals, gain needed skills, and ask for feedback"]'::jsonb,3,'Planned growth supports advancement.','original'),
('127.295.d.1.G',3,'Two job offers pay the same. One adds health insurance. When comparing, you should:','["Weigh salary together with benefits", "Ignore benefits", "Look only at the job title", "Pick by coin flip"]'::jsonb,0,'Total compensation includes benefits.','original'),
('127.295.d.1.G',4,'Which factor is a benefit rather than a salary item?','["Overtime pay", "Paid vacation days", "Annual pay rate", "Hourly wage"]'::jsonb,1,'Paid time off is a benefit.','original'),
('127.295.d.1.H',3,'Which of these is an intangible reward of work?','["A gift card", "A bonus check", "Pride in doing a job well", "A paycheck"]'::jsonb,2,'Intangible rewards are non-monetary feelings and experiences.','original'),
('127.295.d.1.H',4,'A student ranks pay as the most important reward and a friendly team second. These rankings show:','["The only right answer for all workers", "A mistake in thinking", "A legal requirement", "Personal priorities for choosing a job"]'::jsonb,3,'Ranking rewards clarifies what matters to you.','original'),
('127.295.d.1.I',3,'Which source is a common way to find job openings?','["An online job board", "A weather report", "A grocery list", "A random phone number"]'::jsonb,0,'Job boards list current openings.','original'),
('127.295.d.1.I',4,'After finding an opening, the next job search procedure is usually to:','["Wait for the company to call", "Follow the posted instructions to apply by the deadline", "Send a blank form", "Show up uninvited at night"]'::jsonb,1,'Following instructions and deadlines is essential.','original'),
('127.295.d.1.B.i',3,'A letter of application should be addressed to:','["The mailroom only", "A random executive", "The person or department named in the job posting", "Nobody in particular"]'::jsonb,2,'Addressing the right contact shows attention to detail.','original'),
('127.295.d.1.B.i',4,'The best opening for an application letter is one that:','["Asks for a raise", "Complains about unemployment", "Tells a long life story", "States the position you are applying for and why you fit"]'::jsonb,3,'A clear purpose and fit set the tone.','original'),
('127.295.d.1.B.ii',3,'A good resume is usually:','["Brief, accurate, and free of spelling errors", "Many pages of every hobby", "Handwritten on scrap paper", "Full of exaggerated claims"]'::jsonb,0,'Concise, correct resumes make a strong impression.','original'),
('127.295.d.1.B.ii',4,'Which item typically belongs on a resume?','["Your lunch order", "Work experience and relevant skills", "Your favorite color", "A list of your complaints"]'::jsonb,1,'A resume highlights qualifications.','original'),
('127.295.d.1.B.iii',3,'Networking for a job search means:','["Waiting alone", "Only posting memes", "Building contacts who may share job leads and advice", "Avoiding people"]'::jsonb,2,'Networking creates helpful professional connections.','original'),
('127.295.d.1.B.iii',4,'Which action is an effective networking technique?','["Demanding a job at once", "Sending identical spam to strangers", "Ignoring everyone you know", "Asking a family friend in the field for an informational chat"]'::jsonb,3,'Respectful outreach builds relationships.','original'),
('127.295.d.1.B.iv',3,'When completing a job application form, you should:','["Fill in every section accurately and neatly", "Leave blanks to save time", "Write in pencil only", "Guess the dates"]'::jsonb,0,'Accurate, complete applications are taken seriously.','original'),
('127.295.d.1.B.iv',4,'A job application asks for references. You should:','["List strangers", "Ask people for permission before listing them", "List celebrities", "Make up names"]'::jsonb,1,'References should agree to speak for you.','original'),
('127.295.d.1.E.i',3,'After an interview, which follow-up shows good etiquette?','["Complaining on social media", "Calling ten times a day", "A short thank-you note within a day or two", "Silence for months"]'::jsonb,2,'A prompt thank-you shows courtesy.','original'),
('127.295.d.1.E.i',4,'A thank-you letter after an interview should:','["Ask what the company pays", "Criticize other candidates", "Be left unsigned", "Thank the interviewer and restate your interest in the job"]'::jsonb,3,'It reinforces enthusiasm and professionalism.','original'),
('127.295.d.1.E.ii',3,'If you are offered a job you do not want, the polite response is to:','["Write a letter declining the offer with thanks", "Insult the employer", "Show up anyway", "Ignore the offer"]'::jsonb,0,'A courteous decline keeps relationships positive.','original'),
('127.295.d.1.E.ii',4,'A letter accepting a job should confirm:','["Nothing specific", "The position, the start date, and your thanks", "Another job offer", "Your complaints"]'::jsonb,1,'Acceptance letters confirm key terms politely.','original'),
('127.295.d.2.A',3,'Employee handbooks are used to explain:','["The weather", "Vacation destinations", "Workplace policies and procedures", "Local sports"]'::jsonb,2,'Handbooks state rules employees must follow.','original'),
('127.295.d.2.A',4,'An employee sees a safety policy that seems inconvenient. The best response is to:','["Ignore it quietly", "Break it when the boss is away", "Tell coworkers to ignore it", "Follow it and raise concerns through proper channels"]'::jsonb,3,'Policies are followed while concerns go through the right route.','original'),
('127.295.d.2.B',3,'Punctuality at work means:','["Arriving and returning from breaks on time", "Arriving whenever convenient", "Leaving early without notice", "Taking long breaks"]'::jsonb,0,'Being on time shows reliability.','original'),
('127.295.d.2.B',4,'Which statement shows a positive work attitude?','["''I don''t care.''", "''I''ll help with that task.''", "''Someone else will do it.''", "''That''s not my job.''"]'::jsonb,1,'Willingness to help shows a positive attitude.','original'),
('127.295.d.2.C',3,'An employee finds an extra $20 in the cash drawer that is not recorded. The ethical action is to:','["Keep it", "Hide it", "Report it to a supervisor", "Split it with a coworker"]'::jsonb,2,'Honesty requires reporting the difference.','original'),
('127.295.d.2.C',4,'A coworker asks you to clock them in when they are not there. Ethical reasoning says you should:','["Do it if they pay you", "Do it once", "Do it as a favor", "Refuse because it is dishonest"]'::jsonb,3,'Falsifying time records is dishonest.','original'),
('127.295.d.2.D',3,'Producing quality work means:','["Checking your work and fixing errors before turning it in", "Skipping directions", "Leaving it to someone else", "Rushing to finish first"]'::jsonb,0,'Quality comes from careful checking.','original'),
('127.295.d.2.D',4,'Why do employers value high standards for products and services?','["They discourage customers", "They keep customers satisfied and reduce rework", "They make work slower on purpose", "They increase errors"]'::jsonb,1,'Quality reduces waste and builds trust.','original'),
('127.295.d.3.A',3,'Which choice shows good grooming and hygiene for work?','["Stained clothing", "Strong perfume that bothers others", "Clean clothes and neat hair that follow dress policy", "Ignoring the dress code"]'::jsonb,2,'Grooming reflects professionalism.','original'),
('127.295.d.3.A',4,'Why do many workplaces have a dress code?','["To limit friendships", "To raise stress", "To lower pay", "To present a professional image and meet safety needs"]'::jsonb,3,'Dress codes support image and safety.','original'),
('127.295.d.3.B',3,'An employee gets constructive criticism. The best response is to:','["Listen, ask questions, and use the advice", "Argue immediately", "Blame others", "Walk away"]'::jsonb,0,'Accepting feedback supports growth.','original'),
('127.295.d.3.B',4,'Which habit shows productive work habits?','["Texting during shifts", "Staying on task and finishing assignments", "Waiting to be reminded", "Daydreaming"]'::jsonb,1,'Focus and follow-through are productive habits.','original'),
('127.295.d.3.C',3,'Prioritizing work means:','["Doing tasks in random order", "Doing nothing", "Doing the most important or urgent tasks first", "Doing the easiest tasks only"]'::jsonb,2,'Priorities guide the order of tasks.','original'),
('127.295.d.3.C',4,'You have three tasks: one due today, one due Friday, one with no deadline. Best order:','["None until asked", "Friday''s task first", "The open task first", "Today''s task, Friday''s task, then the open task"]'::jsonb,3,'Deadlines set the priority order.','original'),
('127.295.d.4.A',3,'Which quality is a professional quality in the workplace?','["Loyalty to the organization", "Taking credit for others'' work", "Careless attitude", "Gossiping"]'::jsonb,0,'Loyalty and positivity are professional qualities.','original'),
('127.295.d.4.A',4,'A professional who is dependable can be counted on to:','["Blame others", "Do what they promised, on time", "Forget tasks", "Make excuses"]'::jsonb,1,'Dependability means keeping commitments.','original'),
('127.295.d.4.B',3,'Which skill helps keep strong relationships with coworkers?','["Ignoring them", "Interrupting", "Listening and showing respect", "Teasing"]'::jsonb,2,'Respect and listening build relationships.','original'),
('127.295.d.4.B',4,'A coworker is struggling with a task and you finish yours early. A relationship-building move is to:','["Say nothing", "Take their task silently", "Mock them", "Offer help if appropriate"]'::jsonb,3,'Offering help builds trust.','original'),
('127.295.d.4.C',3,'Respecting different workplace cultures means:','["Treating all people and customs with courtesy", "Making fun of unfamiliar customs", "Ignoring differences", "Only talking to similar people"]'::jsonb,0,'Respect supports a good workplace.','original'),
('127.295.d.4.C',4,'A new coworker follows a holiday you do not. A respectful response is to:','["Refuse to work with them", "Ask politely and learn about it", "Stay silent forever", "Laugh at it"]'::jsonb,1,'Curiosity and respect help teams.','original'),
('127.295.d.4.D',4,'An employee who experiences harassment should first:','["Post about it only", "Retaliate", "Report it following the company''s procedure", "Quit without telling anyone"]'::jsonb,2,'Using the reporting process protects rights.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_51_v1'
from (values
('127.295.d.4.E',3,'When a manager points out a mistake, a tactful reply is:','["Silence and a glare", "''It wasn''t me!''", "''You always do this.''", "''Thank you, I''ll fix that.''"]'::jsonb,3,'Tact keeps the conversation productive.','original'),
('127.295.d.4.E',4,'You are disappointed because you did not get the shift you requested. The best response is to:','["Stay calm and ask how to be considered next time", "Gossip about it", "Yell at the scheduler", "Refuse to work"]'::jsonb,0,'Calm requests handle disappointment professionally.','original'),
('127.295.d.4.F',3,'Confidentiality at work means:','["Posting client data online", "Not sharing private information about the company or customers", "Telling everyone secrets", "Selling customer lists"]'::jsonb,1,'Private information must be protected.','original'),
('127.295.d.4.F',4,'Integrity at work is shown by:','["Following rules only when watched", "Cutting corners", "Doing the right thing even when no one is watching", "Lying to avoid blame"]'::jsonb,2,'Integrity is consistent honesty.','original'),
('127.295.d.4.G',3,'Which action improves customer satisfaction?','["Making them wait without explanation", "Ignoring complaints", "Arguing with customers", "Greeting customers politely and solving their problems"]'::jsonb,3,'Courtesy and problem-solving please customers.','original'),
('127.295.d.4.G',4,'A customer''s order is wrong. The best employee response is to:','["Apologize and correct it promptly", "Blame the customer", "Ignore the error", "Tell them to leave"]'::jsonb,0,'A prompt fix keeps customers loyal.','original'),
('127.295.d.5.A',3,'Which trait of a leader builds trust?','["Secrecy about everything", "Honesty", "Blaming the team", "Favoritism"]'::jsonb,1,'Trust is built on honesty and integrity.','original'),
('127.295.d.5.A',4,'A leader who admits a mistake and corrects it shows:','["Carelessness", "A lack of interest", "Integrity and accountability", "Weakness only"]'::jsonb,2,'Owning mistakes builds trust.','original'),
('127.295.d.5.B',3,'Which behavior shows teamwork?','["Working only on your own", "Keeping tools to yourself", "Refusing to listen", "Sharing information so the group can finish together"]'::jsonb,3,'Cooperation helps the whole team.','original'),
('127.295.d.5.B',4,'In a team project, one member finishes early. Good teamwork is to:','["Ask if anyone needs help", "Brag", "Redo others'' work", "Leave quietly"]'::jsonb,0,'Supporting teammates strengthens the group.','original'),
('127.295.d.5.C',3,'Consensus in a team means:','["The boss decides without input", "The group reaches an agreement everyone can support", "A coin flip decides", "The loudest person decides"]'::jsonb,1,'Consensus is shared agreement.','original'),
('127.295.d.5.C',4,'Which activity promotes team building?','["A solo test", "A contest where one wins everything", "A group problem-solving exercise", "Silent work in separate rooms"]'::jsonb,2,'Joint challenges strengthen bonds.','original'),
('127.295.d.5.D',3,'Taking responsibility for shared work means:','["Skipping meetings", "Taking credit for all of it", "Letting others do it", "Completing your part and meeting group deadlines"]'::jsonb,3,'Each member must deliver their part.','original'),
('127.295.d.5.D',4,'A group assignment is late because you did not finish your section. You should:','["Admit it and work with the group to fix it", "Blame the others", "Disappear", "Deny it"]'::jsonb,0,'Accountability protects the team.','original'),
('127.295.d.5.E.i',3,'Showing respect toward coworkers includes:','["Interrupting", "Using polite language and valuing their ideas", "Name-calling", "Ignoring ideas"]'::jsonb,1,'Respect builds working relationships.','original'),
('127.295.d.5.E.i',4,'Which message shows respect in a disagreement?','["''You never listen.''", "''That''s a stupid idea.''", "''I see it differently; may I explain?''", "''Whatever.''"]'::jsonb,2,'Respectful phrasing keeps discussion open.','original'),
('127.295.d.5.E.ii',3,'Which statement is positive communication?','["''You messed up again.''", "''Figure it out.''", "''Not my problem.''", "''Thanks for your help on that.''"]'::jsonb,3,'Positive communication encourages cooperation.','original'),
('127.295.d.5.E.ii',4,'A coworker made a small mistake. A positive way to say it is:','["''Let''s fix this together.''", "''You''re hopeless.''", "''I told you so.''", "''Look what you did!''"]'::jsonb,0,'Constructive language focuses on solutions.','original'),
('127.295.d.5.E.iii',3,'Negotiating a solution means:','["Refusing to talk", "Working out a compromise that satisfies both sides", "Demanding your way", "Giving in completely"]'::jsonb,1,'Negotiation seeks a fair compromise.','original'),
('127.295.d.5.E.iii',4,'Two coworkers want the same break time. A fair negotiation might be to:','["Argue until one quits", "Report each other", "Trade times and alternate days", "Flip tables"]'::jsonb,2,'Compromise resolves conflicts fairly.','original'),
('127.295.d.5.E.iv',3,'Demonstrating dependability includes:','["Making excuses", "Avoiding responsibility", "Missing deadlines", "Following through on commitments"]'::jsonb,3,'Dependable people can be counted on.','original'),
('127.295.d.5.E.iv',4,'A dependable employee who is going to be absent should:','["Notify the supervisor as early as possible", "Call after the shift", "Not come and say nothing", "Send a friend with no message"]'::jsonb,0,'Early notice lets the team plan.','original'),
('127.295.d.6.A',3,'When taking a phone message, you should record the caller''s name, number, and:','["Nothing else", "The message and the date and time", "A joke", "Your opinion of the caller"]'::jsonb,1,'Complete messages are useful and accurate.','original'),
('127.295.d.6.A',4,'Why should a recorded message be legible?','["To use more paper", "To hide the content", "So the person receiving it can read it correctly", "To impress the caller"]'::jsonb,2,'Legibility prevents errors.','original'),
('127.295.d.6.B',3,'A message is for the sales department. You should:','["Keep it on your desk", "Throw it away", "Give it to anyone", "Deliver it to the sales department promptly"]'::jsonb,3,'Messages go to the right person quickly.','original'),
('127.295.d.6.B',4,'You do not know who should receive a call. The best step is to:','["Ask a supervisor or check the directory", "Guess and transfer randomly", "Tell the caller to call back later", "Hang up"]'::jsonb,0,'Finding the right contact helps the caller.','original'),
('127.295.d.6.C',3,'Coordinating arrangements for participants in a conference call includes:','["Cancelling without notice", "Confirming times and sending the dial-in information", "Sending the wrong date", "Telling no one"]'::jsonb,1,'Participants need correct details.','original'),
('127.295.d.6.C',4,'Before a video meeting, a coordinator should:','["Skip invitations", "Join late", "Test the connection and share an agenda", "Mute the speaker"]'::jsonb,2,'Preparation helps the meeting run well.','original'),
('127.295.d.6.D',3,'Calling procedures usually require you to:','["Give out private passwords", "Answer with slang", "Hang up if a call is long", "Identify yourself and the company at the start of a call"]'::jsonb,3,'Standard greetings sound professional.','original'),
('127.295.d.6.D',4,'Before joining a conference line, you often need to:','["Enter the correct meeting ID or login", "Guess a code", "Use someone else''s account", "Skip the login"]'::jsonb,0,'Login steps secure the meeting.','original'),
('127.295.d.6.E',3,'If the call audio is not working, the first thing to try is to:','["Cancel the meeting", "Check the volume, microphone, and connection", "Shout", "Throw the phone"]'::jsonb,1,'Basic checks fix many problems.','original'),
('127.295.d.6.E',4,'A call keeps dropping. A good troubleshooting step is to:','["Ignore it", "Delete the account", "Move to a stronger network or call back", "Blame the caller"]'::jsonb,2,'Fix the likely cause first.','original'),
('127.295.d.7.A',3,'An acceptable use policy tells employees:','["What to eat", "The weather forecast", "How to dress for sports", "How company technology may and may not be used"]'::jsonb,3,'It sets rules for technology.','original'),
('127.295.d.7.A',4,'Which action breaks a technology security policy?','["Sharing your password with a coworker", "Locking your screen", "Updating software", "Logging out"]'::jsonb,0,'Passwords should never be shared.','original'),
('127.295.d.7.B',3,'A good ergonomic habit when using a computer is to:','["Slouch for hours", "Sit with your back supported and the screen at eye level", "Place the screen on the floor", "Type with your wrists bent up"]'::jsonb,1,'Ergonomics prevents strain.','original'),
('127.295.d.7.B',4,'Taking short breaks from a screen helps prevent:','["Internet outages", "Software updates", "Eye strain and muscle fatigue", "Spelling errors"]'::jsonb,2,'Breaks reduce physical strain.','original'),
('127.295.d.7.C',3,'Computer crime includes:','["Printing a page", "Typing a report", "Saving a file", "Hacking into a system without permission"]'::jsonb,3,'Unauthorized access is a crime.','original'),
('127.295.d.7.C',4,'Using someone else''s credit card number found online is:','["Fraud, which is illegal", "A way to test security", "Legal if small", "A harmless prank"]'::jsonb,0,'Using stolen numbers is fraud.','original'),
('127.295.d.7.D',3,'After a power outage, you should restart a computer by:','["Tapping the keys randomly", "Following the organization''s recovery steps", "Unplugging all cords", "Opening a hammer"]'::jsonb,1,'Recovery steps prevent data loss.','original'),
('127.295.d.7.D',4,'If a system crashes while you work, the first thing to check later is:','["Your lunch", "Whether the monitor is blue", "Whether your most recent work was saved or recovered", "The weather"]'::jsonb,2,'Recovering unsaved work matters.','original'),
('127.295.d.7.E',3,'To protect data integrity, an employee should:','["Ignore errors", "Share one account", "Delete the original", "Back up files regularly"]'::jsonb,3,'Backups prevent loss.','original'),
('127.295.d.7.E',4,'Which practice helps prevent accidental changes to important records?','["Limiting who can edit them", "Letting everyone edit", "Removing the backup", "Leaving files unprotected"]'::jsonb,0,'Access controls protect integrity.','original'),
('127.295.d.7.F',3,'Using work computers for personal shopping during work hours usually:','["Is always allowed", "Violates technology use policy", "Is required", "Raises productivity"]'::jsonb,1,'Policies limit personal use.','original'),
('127.295.d.7.F',4,'Before installing new software on a work computer, you should:','["Install anything you like", "Ignore the IT team", "Get approval under company policy", "Disable security"]'::jsonb,2,'Unapproved software can threaten security.','original'),
('127.295.d.8.A',3,'For an advanced web search, a good way to narrow results is to:','["Type one vague word", "Click the first ad", "Search only images", "Use specific keywords and quotation marks for exact phrases"]'::jsonb,3,'Specific searches yield better results.','original'),
('127.295.d.8.A',4,'A source for research is most reliable when it is:','["From an established, credible organization", "A rumor", "An anonymous post", "A joke site"]'::jsonb,0,'Credibility matters for research.','original'),
